<script setup>
import ListPagination from '../../shared/components/ListPagination.vue'




import DateRangeFilter from '../../shared/components/DateRangeFilter.vue'
import {workItemSourceOptions,workItemSourceHelp} from '../workItemSources.js'

import {computed, inject, nextTick, onBeforeUnmount, ref, watch} from 'vue'

import HelpTip from '../../shared/components/HelpTip.vue'
import RichDescription from './RichDescription.vue'

import {issueStatus, sourcePerson, personOptions, issueDate, workSelectionKey as keyOf} from '../../shared/issuePresentation.js'
const props=defineProps({show:Boolean,purpose:{type:String,default:'version'},ids:{type:Array,default:()=>[]},seed:{type:Array,default:()=>[]},me:{type:Object,default:()=>({})},environments:{type:Array,default:()=>[]},versionID:{type:Number,default:0}})
const emit=defineEmits(['close','confirm']),api=inject('api')
const limitNotice=ref('')
const showNumbers=ref(false),showAdvanced=ref(false),showSelected=ref(false),numberError=ref(''),optionsLoading=ref(false),tableRegion=ref(null),tableHeight=ref(320)
let tableObserver
const sourceConnections=ref([]),personLabels=ref({}),products=ref({}),product=ref('0'),mineOnly=ref(false),hasMore=ref(false),exactTotal=ref(true),cursors=ref(['']),confirming=ref(false),confirmedCount=ref(0)
const live=computed(()=>true)
const sourceOptions=computed(()=>workItemSourceOptions(sources.value,sourceConnections.value))
const localPersonLabels=ref({})
const knownPersonLabels=computed(()=>{const names={},conflicts=new Set();for(const labels of Object.values(localPersonLabels.value))for(const [key,name] of Object.entries(labels)){if(names[key]&&names[key]!==name)conflicts.add(key);names[key]=name}for(const key of conflicts)delete names[key];return names})
const peopleOptions=computed(()=>personOptions(people.value,live.value?personLabels.value:knownPersonLabels.value))
const rowPerson=w=>sourcePerson(w.resolved_by,{...w.person_labels,...localPersonLabels.value[w.source],...(live.value?personLabels.value:{})})
const filters=ref({q:'',kind:'bug',status:'closed',source:'',person:'',person_role:'resolved_by',environment:'',delivery:'',planning:'',start:'',end:'',numbers:'',release_required:'eligible',time_field:'closed'})
const items=ref([]),people=ref([]),sources=ref([]),page=ref(1),size=ref(20),total=ref(0),loading=ref(false),hydrating=ref(false),error=ref(''),optionsError=ref(''),selectionError=ref(''),selected=ref(new Map()),peek=ref(null),peekLoading=ref(false),numberInput=ref('')
let session=0,sequence=0,peekSequence=0,selectionSequence=0,optionsSequence=0,timer,initialized=false
const chosen=computed(()=>[...selected.value.values()])
const invalidSelected=computed(()=>chosen.value.filter(w=>w.missing).length)
const allOnPage=computed(()=>items.value.length>0&&items.value.every(i=>selected.value.has(keyOf(i))))
const canMine=computed(()=>props.me.username&&props.me.username!=='local'&&props.me.auth_enabled!==false)
const canConfirm=computed(()=>!confirming.value&&!hydrating.value&&!selectionError.value&&chosen.value.length<=500&&chosen.value.every(w=>w.checked&&!w.missing))
const statusLabel=issueStatus
const pages=computed(()=>Math.max(1,Math.ceil(total.value/size.value)))
const date=n=>n?new Date(n*1000).toLocaleDateString('zh-CN'):'—'
const roles=[{value:'resolved_by',label:'由谁解决'},{value:'related',label:'相关人员'},{value:'assigned_to',label:'指派给'},{value:'opened_by',label:'由谁创建'},{value:'closed_by',label:'由谁关闭'},{value:'owner',label:'自定义创建人'}]
const releaseOptions=[{value:'eligible',label:'需上线或待判定'},{value:'yes',label:'需要上线'},{value:'unknown',label:'上线待判定'},{value:'no',label:'不需要上线'}]
const dateLabel=computed(()=>filters.value.time_field==='closed'?'Bug 关闭时间':live.value?'来源更新时间':'平台更新时间')
const bugPreset=computed(()=>filters.value.kind==='bug'&&filters.value.status==='closed'&&filters.value.release_required==='eligible'&&filters.value.time_field==='closed'&&filters.value.delivery===(filters.value.environment?'not_recorded':'')&&!filters.value.planning)
const requirementPreset=computed(()=>filters.value.kind==='requirement'&&!filters.value.status&&!filters.value.release_required)
const activeFilters=computed(()=>{
 const f=filters.value,result=[]
 const add=(key,label)=>{if(f[key])result.push({key,label})}
 add('release_required',releaseOptions.find(v=>v.value===f.release_required)?.label||f.release_required)
 add('person',(roles.find(v=>v.value===f.person_role)?.label||'人员')+'：'+(peopleOptions.value.find(v=>v.value===f.person)?.label||f.person))
 add('environment','上线环境：'+(props.environments.find(v=>v.name===f.environment)?.display_name||f.environment))
 add('delivery',f.delivery==='recorded'?'已有成功记录':'无成功记录（待核对）')
 add('planning',f.planning==='planned'?'其他版本已排期':'未被其他版本排期')
 if(f.start||f.end)result.push({key:'dates',label:dateLabel.value+'：'+(f.start||'不限')+'～'+(f.end||'不限')})
 if(f.numbers)result.push({key:'numbers',label:'编号清单已生效'})
 if(live.value&&product.value!=='0')result.push({key:'product',label:'产品：'+(products.value[product.value]||product.value)})
 return result
})
function clearFilter(key){if(key==='dates'){filters.value.start='';filters.value.end=''}else if(key==='product')product.value='0';else{filters.value[key]='';if(key==='numbers')numberInput.value=''}}
watch([()=>props.show,tableRegion],async()=>{
 tableObserver?.disconnect()
 if(!props.show||!tableRegion.value)return
 const region=tableRegion.value
 await nextTick()
 if(!props.show||tableRegion.value!==region||!region.isConnected)return
 tableObserver=new ResizeObserver(([entry])=>{const head=tableRegion.value?.querySelector('.arco-table-header')?.getBoundingClientRect().height||40;tableHeight.value=Math.max(80,Math.floor(entry.contentRect.height-head-18))})
 tableObserver.observe(region)
},{flush:'post'})
async function loadPage(){
 const generation=session,request=++sequence;loading.value=true;error.value='';items.value=[]
 const q=new URLSearchParams({page:String(page.value),page_size:String(size.value),version_id:String(props.versionID),mine:!live.value&&filters.value.person===props.me.username?'1':''})
 for(const [k,v] of Object.entries(filters.value))if(v)q.set(k,['start','end'].includes(k)?String(Math.floor(new Date(v+(k==='start'?'T00:00:00':'T23:59:59')).getTime()/1000)):v)
 if(filters.value.source.startsWith('managed:'))q.set('source',filters.value.source.slice(8))
 if(filters.value.time_field==='closed'){q.set('source_start',filters.value.start);q.set('source_end',filters.value.end);q.delete('start');q.delete('end')}
 if(live.value){
  q.set('connection',filters.value.source);q.set('product',filters.value.source?product.value:'0');q.set('kind',filters.value.kind);q.set('mine',mineOnly.value?'1':'');q.set('person_role',filters.value.person_role==='related'?'assigned_to':filters.value.person_role);q.set('cursor',cursors.value[page.value-1]||'');q.set('source_start',filters.value.start);q.set('source_end',filters.value.end)
  q.delete('start');q.delete('end');q.delete('numbers');q.delete('planning');
  if(filters.value.delivery==='recorded')q.set('delivery','')
 }
 try{const data=await api('api/research/work-items/page?'+q);if(generation!==session||request!==sequence||!props.show)return;if(!Array.isArray(data.items)||!Number.isInteger(data.total)||data.total<0||!Number.isInteger(data.page)||data.page<1)throw Error('候选列表响应无效');items.value=data.items;total.value=data.total;page.value=data.page;exactTotal.value=data.total_exact!==false;hasMore.value=data.has_more??data.page*size.value<data.total;cursors.value[page.value]=data.next_cursor||'';if(live.value){personLabels.value=data.people||{};people.value=Object.keys(personLabels.value);products.value=data.products||{}}else{const labels={};for(const item of data.items)Object.assign(labels,item.person_labels||{});personLabels.value=labels}}
 catch(e){if(generation===session&&request===sequence&&props.show){error.value=e.message;total.value=0}}
 finally{if(generation===session&&request===sequence)loading.value=false}
}
async function hydrate(){
 const generation=session,request=++selectionSequence;hydrating.value=true;selectionError.value=''
 const ids=[...selected.value.values()].filter(w=>w.id).map(w=>w.id)
 try{
  if(ids.length){const data=await api('api/work-items/candidates/selected?'+new URLSearchParams({ids:ids.join(','),environment:filters.value.environment,version_id:String(props.versionID)}));if(generation!==session||request!==selectionSequence||!props.show)return;const map=new Map(data.items.map(w=>[keyOf(w),{...w,checked:true}]));for(const id of ids)if(selected.value.has(String(id)))selected.value.set(String(id),map.get(String(id))||{id,title:'记录不存在，请移除 #'+id,missing:true,checked:true})}
 }catch(e){if(generation===session&&request===selectionSequence)selectionError.value='已选记录校验失败：'+e.message}
 finally{if(generation===session&&request===selectionSequence)hydrating.value=false}
}
function toggle(w){limitNotice.value='';const key=keyOf(w);if(selected.value.has(key)){selected.value.delete(key);selectionError.value=''}else if(selected.value.size<500)selected.value.set(key,{...w,checked:true,from_live:w.source?.startsWith('zentao:')});else limitNotice.value='最多选择 500 项，当前选择未改变，请先移除部分记录'}
function togglePage(){limitNotice.value='';if(allOnPage.value){for(const w of items.value)selected.value.delete(keyOf(w))}else{const added=items.value.filter(w=>!selected.value.has(keyOf(w)));if(selected.value.size+added.length>500){limitNotice.value='选择本页将超过 500 项，未改变当前选择；可逐项选择或先移除部分记录';return}for(const w of added)selected.value.set(keyOf(w),{...w,checked:true,from_live:w.source?.startsWith('zentao:')})}}
function preset(kind){if(kind==='requirements')filters.value.source='';filters.value.kind=kind==='requirements'?'requirement':'bug';filters.value.status=kind==='requirements'?'':'closed';filters.value.release_required=kind==='requirements'?'':'eligible';filters.value.time_field=kind==='requirements'?'updated':'closed';filters.value.delivery=filters.value.environment?'not_recorded':'';filters.value.planning=''}
function mine(){if(live.value){mineOnly.value=!mineOnly.value;filters.value.person='';filters.value.person_role='resolved_by';page.value=1;cursors.value=[''];loadPage()}else{filters.value.person_role='related';filters.value.person=filters.value.person===props.me.username?'':props.me.username}}
function go(n){page.value=n;loadPage()}
function applyNumbers(){if(!filters.value.source||filters.value.source==='manual'){numberError.value='请先选择一个来源，再筛选外部编号';return}numberError.value='';filters.value.numbers=numberInput.value;showNumbers.value=false}
async function preview(w){
 if(!w.id){peek.value={...w,description:'确认选择后会关联交付内容；不会修改来源平台。'};return}
 const generation=session,request=++peekSequence;peek.value={...w};peekLoading.value=true
 try{const full=await api('api/work-items/'+w.id);if(generation===session&&request===peekSequence&&props.show)peek.value=full}catch(e){if(generation===session&&request===peekSequence)peek.value={...w,description:'详情读取失败：'+e.message}}finally{if(generation===session&&request===peekSequence)peekLoading.value=false}
}
async function confirm(){
 if(!canConfirm.value)return;showAdvanced.value=false;showNumbers.value=false;confirming.value=true;confirmedCount.value=0;selectionError.value=''
 try{const result=[];for(const value of chosen.value){let row=value;if(value.from_live){const item=await api('api/research/work-items/attach',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({connection:value.source.slice(7),external_id:value.external_id})});selected.value.delete(keyOf(value));row={...value,...item,from_live:false,checked:true};selected.value.set(keyOf(row),row)}result.push(row);confirmedCount.value++}emit('confirm',result)}catch(e){selectionError.value=`来源关联失败：${e.message}。已关联 ${confirmedCount.value} 项；已选清单保留，尚未提交${props.purpose==='delivery'?'交付':props.purpose==='document-report'?'上报关联':'版本'}。`}finally{confirming.value=false}
}
async function loadOptions(){
 const generation=session,request=++optionsSequence;optionsError.value='';optionsLoading.value=true
 const results=await Promise.allSettled(['api/work-items/people','api/research/work-items/sources','api/work-items/people-labels'].map(path=>api(path)))
 if(generation!==session||request!==optionsSequence||!props.show)return
 const targets=[people,sourceConnections,localPersonLabels],labels=['人员','来源连接','人员名称'],failed=[]
 results.forEach((result,index)=>{if(result.status==='fulfilled'&&(index===2?result.value&&typeof result.value==='object'&&!Array.isArray(result.value):Array.isArray(result.value)))targets[index].value=result.value;else failed.push(labels[index])})
 optionsError.value=failed.length?failed.join('、')+'读取失败，其他筛选仍可使用':'';optionsLoading.value=false
}
watch(()=>props.show,async opened=>{
 showNumbers.value=false;showAdvanced.value=false;showSelected.value=false;numberError.value=''
 session++;sequence++;peekSequence++;selectionSequence++;clearTimeout(timer);peek.value=null;error.value='';selectionError.value='';limitNotice.value=''
 if(!opened)return
 const seed=new Map(props.seed.map(w=>[w.id,w]));selected.value=new Map(props.ids.map(id=>[String(id),seed.get(id)||{id,title:'正在加载 #'+id}]))
 if(!initialized&&props.purpose==='document-report'){filters.value={...filters.value,kind:'',status:'',release_required:'',environment:'',delivery:'',time_field:'updated'};initialized=true}
 if(!initialized){const prod=props.environments.find(e=>e.purpose==='production')||props.environments.find(e=>e.name==='prod');filters.value.environment=prod?.name||'';filters.value.delivery=prod?'not_recorded':'';initialized=true}
 loadOptions()
 await nextTick();loadPage();hydrate()
})
watch(filters,()=>{
 if(!props.show)return
 page.value=1;cursors.value=[''];sequence++;clearTimeout(timer);loading.value=true;items.value=[]
 timer=setTimeout(loadPage,250)
},{deep:true})
watch(size,()=>{if(props.show){page.value=1;loadPage()}})
watch(()=>filters.value.kind,value=>{if(value!=='bug')filters.value.time_field='updated'})
watch(()=>filters.value.environment,value=>{if(!value)filters.value.delivery='';if(props.show)hydrate()})
watch(()=>filters.value.source,()=>{personLabels.value={};people.value=[];product.value='0';mineOnly.value=false;filters.value.person='';filters.value.numbers='';if(live.value){if(filters.value.source)filters.value.kind='bug';filters.value.person_role='resolved_by';filters.value.planning='';if(filters.value.delivery==='recorded')filters.value.delivery=''}else loadOptions()})
watch(product,()=>{if(props.show&&live.value){page.value=1;cursors.value=[''];loadPage()}})
onBeforeUnmount(()=>{session++;sequence++;peekSequence++;clearTimeout(timer);tableObserver?.disconnect()})

import OptionPicker from '../../shared/components/OptionPicker.vue'



import {Badge,Button,Checkbox,Dialog,DialogContent,DialogDescription,DialogFooter,DialogHeader,DialogTitle,Empty,EmptyContent,EmptyDescription,EmptyHeader,Input,Popover,PopoverContent,PopoverTrigger,Spinner,Table,TableBody,TableCell,TableHead,TableHeader,TableRow,Textarea} from '../../shared/shadcn-ui.js'

import {InputGroup,InputGroupInput,InputGroupAddon,InputGroupButton} from '../../shared/shadcn-ui.js'

import {XIcon} from '@lucide/vue'
</script>
<template><Dialog :open="show" @update:open="async v=>{if(!v){!confirming&amp;&amp;emit('close')}}"><DialogContent class="flex max-h-[92dvh] flex-col gap-0 overflow-hidden p-0 sm:max-w-[var(--editor-width)]" :class="false?'inset-0 h-dvh max-h-dvh w-screen max-w-none translate-x-0 translate-y-0 rounded-none sm:max-w-none':''" :style="{'--editor-width':typeof (&quot;min(1440px, 96vw)&quot;)==='number'?(&quot;min(1440px, 96vw)&quot;)+'px':(&quot;min(1440px, 96vw)&quot;)}" :show-close-button="!confirming" @interact-outside="e=>{if(!(!confirming))e.preventDefault()}" @escape-key-down="e=>{if(!(!confirming))e.preventDefault()}"><DialogHeader class="shrink-0 border-b p-5 pr-12"><DialogTitle>选择需求与 BUG</DialogTitle><DialogDescription class="sr-only">详情与操作</DialogDescription></DialogHeader><div class="min-h-0 flex-1 overflow-auto p-5"><fieldset :disabled="confirming" :aria-busy="loading||confirming" class="work-picker"><div class="picker-presets"><Button @click="preset('bugs')" :variant="({primary:'default',secondary:'outline',text:'ghost',outline:'outline',dashed:'outline'})[bugPreset?'primary':'secondary']||'outline'" size="sm" type="button">待上线 BUG</Button><Button @click="preset('requirements')" :variant="({primary:'default',secondary:'outline',text:'ghost',outline:'outline',dashed:'outline'})[requirementPreset?'primary':'secondary']||'outline'" size="sm" type="button">选择需求</Button><Button @click="mine" :variant="({primary:'default',secondary:'outline',text:'ghost',outline:'outline',dashed:'outline'})[(live?mineOnly:filters.person===me.username)?'primary':'secondary']||'outline'" size="sm" type="button" :disabled="(!canMine)">只看我的</Button><HelpTip text="可跨页选择，最多 500 项。所有来源工作项实时查询，确认后关联交付内容，不修改来源 Bug。待上线 BUG 筛选已关闭、需上线或待判定且所选环境无成功记录的工作项；无成功记录不代表确定未上线，其他版本排期也只作提示。"/><span class="picker-scope">实时查询</span><Button :aria-expanded="showSelected" @click="showSelected=!showSelected;peek=null" class="selected-trigger" :variant="({primary:'default',secondary:'outline',text:'ghost',outline:'outline',dashed:'outline'})[showSelected?'primary':'outline']||'outline'" size="sm" type="button" :disabled="(hydrating)"><Spinner v-if="hydrating"/>已选 {{selected.size}} 项</Button></div><div class="picker-filters"><InputGroup  class="min-w-0 picker-search"><InputGroupInput v-model="filters.q" placeholder="搜索标题、外部编号或 #平台编号" v-bind="{'aria-label':'搜索候选需求'}"/><InputGroupAddon align="inline-end"><InputGroupButton v-if="filters.q" :disabled="false" size="icon-xs" aria-label="清空输入" @click="filters.q='' "><XIcon/></InputGroupButton></InputGroupAddon></InputGroup><OptionPicker v-model="filters.kind" :disabled="!!filters.source" :options="[{value:'bug',label:'BUG'},{value:'requirement',label:'需求'}]" all-label="全部类型" :style="{width:'110px',maxWidth:'100%'}" aria-label="候选类型"/><OptionPicker v-model="filters.status" :options="[{value:'closed',label:'已关闭'},{value:'resolved',label:'已解决'},{value:'active',label:'激活'},{value:'open',label:'未关闭'}]" all-label="全部状态" :style="{width:'120px',maxWidth:'100%'}" aria-label="候选状态"/><div role="group" aria-label="工作项来源筛选" class="inline-flex min-w-0 max-w-full items-center gap-1"><OptionPicker v-model="filters.source" :options="sourceOptions" all-label="全部来源"  :style="{width:'240px',maxWidth:'100%'}" aria-label="候选来源"/><HelpTip :text="workItemSourceHelp"/></div><Popover v-model:open="showAdvanced"><PopoverTrigger as-child><Button :aria-expanded="showAdvanced" variant="outline" size="default" type="button">更多筛选{{activeFilters.length?' · '+activeFilters.length:''}}</Button></PopoverTrigger><PopoverContent class="max-h-[80dvh] max-w-[calc(100vw-2rem)] overflow-auto" align="end" :style="{width:'min(620px, calc(100vw - 48px))'}"><div role="dialog" aria-label="更多筛选条件" @keydown.esc.stop.prevent="showAdvanced=false" class="advanced-filters"><div class="advanced-heading"><b>更多筛选</b><Button aria-label="收起更多筛选" @click="showAdvanced=false" variant="ghost" size="sm" type="button">收起</Button></div><div class="advanced-grid"><div class="filter-field"><span>上线意图</span><OptionPicker v-model="filters.release_required" :options="releaseOptions" all-label="全部上线意图" :style="{width:'100%',maxWidth:'100%'}" aria-label="上线意图"/></div><div v-if="filters.source" class="filter-field"><span>产品</span><OptionPicker v-model="product" :options="[{value:'0',label:'全部允许产品'},...Object.entries(products).map(([value,label])=>({value,label}))]"  :style="{width:'100%',maxWidth:'100%'}" aria-label="候选产品"/></div><div class="filter-field"><span>人员关系</span><OptionPicker v-model="filters.person_role" :options="live?roles.filter(r=>!['related','owner'].includes(r.value)):roles" :style="{width:'100%',maxWidth:'100%'}" aria-label="候选人员关系"/></div><div class="filter-field"><span>人员</span><OptionPicker v-model="filters.person" :disabled="live&&mineOnly" :options="peopleOptions"  all-label="全部人员" :style="{width:'100%',maxWidth:'100%'}" aria-label="候选人员"/></div><div class="filter-field"><span>上线环境</span><OptionPicker v-model="filters.environment" :options="environments.map(e=>({value:e.name,label:e.display_name||e.name}))" all-label="全部环境" :style="{width:'100%',maxWidth:'100%'}" aria-label="上线环境"/></div><div class="filter-field"><span>上线记录</span><OptionPicker v-model="filters.delivery" :disabled="!filters.environment" :options="[{value:'not_recorded',label:'无成功记录（待核对）'},...(!live?[{value:'recorded',label:'已有成功记录'}]:[])]" all-label="全部上线记录" :style="{width:'100%',maxWidth:'100%'}" aria-label="候选上线记录"/></div><div v-if="!live" class="filter-field"><span>版本排期</span><OptionPicker v-model="filters.planning" :options="[{value:'unplanned',label:'未被其他版本排期'},{value:'planned',label:'其他版本已排期'}]" all-label="全部排期" :style="{width:'100%',maxWidth:'100%'}" aria-label="候选排期"/></div><div class="filter-field"><span>时间类型 <HelpTip text="Bug 关闭时间按来源记录的关闭日期筛选。缺少关闭时间的记录不会命中。不会使用平台更新时间替代。"/></span><OptionPicker v-model="filters.time_field" :options="[...(filters.kind==='bug'?[{value:'closed',label:'Bug 关闭时间'}]:[]),{value:'updated',label:live?'来源更新时间':'平台更新时间'}]" :style="{width:'1