plate></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:w,rowIndex:rowIndex} in [{record,rowIndex}]"><div>{{w.external_id||'#'+w.id}}<small>{{w.kind==='bug'?'BUG':'需求'}} · {{w.source==='manual'?'自定义':w.source}}</small></div></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:w,rowIndex:rowIndex} in [{record,rowIndex}]"><div><Button :title="w.title+' · '+dateLabel+'：'+(filters.time_field==='closed'?(w.source_closed_at||'未采集'):(live?issueDate(w.source_updated_at):date(w.updated_at)))" @click="preview(w)" class="picker-title" variant="ghost" size="sm" type="button">{{w.title}}</Button></div></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:w,rowIndex:rowIndex} in [{record,rowIndex}]"><div>{{statusLabel(w)}}<small>{{rowPerson(w)}}</small></div></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:w,rowIndex:rowIndex} in [{record,rowIndex}]"><div :class="{attention:!w.change_count||w.ready_count<w.change_count}">{{w.change_count===undefined?'交付内容待核对':w.change_count?w.ready_count+' / '+w.change_count+' 项就绪':'待补充交付内容'}}</div></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:w,rowIndex:rowIndex} in [{record,rowIndex}]"><div><small>{{w.successful_delivery?'完整交付记录':w.partial_delivery?'部分交付，尚有未发布变更':'历史上线待核对'}}</small><small v-if="w.planned_count">{{w.planned_count}} 个其他版本已排期</small></div></template></div></TableCell></TableRow></template><TableRow v-if="!(items.map(w=>({...w,__rowKey:keyOf(w)}))||[]).length"><TableCell :colspan="6"><Empty><EmptyHeader><EmptyDescription><span v-if="loading">正在查询候选…</span><template v-else-if="error"><p role="alert">{{error}}</p><Button @click="loadPage" variant="outline" size="default" type="button">重试</Button></template><span v-else>没有匹配项，可调整状态、人员或日期；已选清单不会丢失。</span></EmptyDescription></EmptyHeader></Empty></TableCell></TableRow></TableBody></Table></div></div></div><div class="table-footer"><span v-if="!exactTotal" class="table-summary">来源候选 {{total}} 项（按允许范围过滤）</span><ListPagination v-if="exactTotal" :page="page" :total="total" :page-size="size" :disabled="loading" @update:page="go($event)" @update:page-size="size=$event"/><template v-else><OptionPicker v-model="size" :options="[20,50,100].map(value=>({value,label:value+' 项 / 页'}))" :style="{width:'120px',maxWidth:'100%'}"/><Button @click="go(page-1)" variant="outline" size="default" type="button" :disabled="(loading||page<=1)">上一页</Button><span>第 {{page}} 页</span><Button @click="go(page+1)" variant="outline" size="default" type="button" :disabled="(loading||!hasMore)">下一页</Button></template></div></div><aside v-if="peek" aria-label="工作项详情预览" class="picker-panel"><div class="selected-heading"><b>{{peek.external_id||'#'+peek.id}} · 详情</b><Button @click="peek=null;peekSequence++" variant="ghost" size="sm" type="button">关闭预览</Button></div><div class="preview-body"><h3>{{peek.title}}</h3><p v-if="peekLoading">正在读取详情…</p><RichDescription v-else :content="peek.description||''" :format="peek.description_format||''" :source-url="peek.url||''" title="工作项详情"/></div></aside><aside v-else-if="showSelected" aria-label="跨页已选清单" class="picker-panel"><div class="selected-heading"><b>已选 {{selected.size}} / 500 项</b><Button @click="selected.clear();selectionError=''" variant="ghost" size="sm" type="button" :disabled="(hydrating)">清空</Button><Button @click="showSelected=false" variant="ghost" size="sm" type="button">收起</Button></div><p v-if="hydrating" role="status">正在核对已选记录…</p><div class="selected-list"><article v-for="w in chosen" :key="keyOf(w)"><span :title="w.title">{{w.external_id||'#'+w.id}} · {{w.title}}</span><Button :aria-label="'移除 '+(w.external_id||'#'+w.id)" @click="selected.delete(keyOf(w));selectionError=''" variant="ghost" size="sm" type="button" :disabled="(hydrating)">移除</Button><small v-if="w.missing" class="attention">记录已失效，请移除</small><small v-else-if="w.change_count===0" class="attention">待补充变更，保存草稿后完善</small></article><Empty v-if="!chosen.length"><EmptyHeader><EmptyDescription>{{"勾选表格记录，可跨页累计"}}</EmptyDescription></EmptyHeader></Empty></div></aside></div><footer class="picker-footer"><span>{{confirming?'正在关联来源 '+confirmedCount+' / '+selected.size+' 项…':'已选 '+selected.size+' / 500 项 · 跨页保留'}}<HelpTip :text="purpose==='delivery'?'仅选择交付范围，不构建、不执行或发布。':purpose==='document-report'?'仅记录本次上报对应的需求或Bug，不审批、不修改需求状态。':'仅调整版本草稿，不保存版本、不构建或发布。'"/></span><Button @click="emit('close')" variant="outline" size="default" type="button" :disabled="(confirming)">取消，保留原选择</Button><Button @click="confirm" variant="default" size="default" type="button" :disabled="(!canConfirm)||(confirming)"><Spinner v-if="confirming"/>{{purpose==='document-report'?'保存关联':'确认选择'}} {{selected.size}} 项</Button></footer></fieldset></div></DialogContent></Dialog></template>
