.picker-title{width:100%;justify-content:flex-start;text-align:left;white-space:normal}
.picker-panel{min-width:0;min-height:0;padding:12px;border:1px solid var(--border);border-radius:var(--radius);display:flex;flex-direction:column;background:var(--card);overflow:hidden}.selected-heading{font-size:.875rem;gap:4px}.selected-heading>b{margin-right:auto}.selected-list,.preview-body{overflow:auto;min-height:0;flex:1}.selected-list article{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:4px;align-items:start;padding:12px 0;border-bottom:1px solid var(--border)}.selected-list article>span{overflow-wrap:anywhere;font-size:.875rem}.selected-list small{grid-column:1/-1}.preview-body h3{font-size:1rem;overflow-wrap:anywhere}.attention{color:var(--warn)!important}
.picker-footer{border-top:1px solid var(--border);padding-top:12px}.picker-footer>span{display:flex;align-items:center;gap:6px;margin-right:auto;font-size:.75rem;color:var(--muted-foreground)}
.advanced-filters,.number-filter{display:grid;gap:16px}.advanced-heading{display:flex;align-items:center;justify-content:space-between}.advanced-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.filter-field{display:grid;gap:6px;min-width:0}.filter-field>span{font-size:.875rem;color:var(--muted-foreground)}.number-filter small{color:var(--muted-foreground);font-size:.75rem;line-height:1.6}.number-filter>div{display:flex;justify-content:flex-end;gap:8px}.number-filter p{margin:0;font-size:.75rem}
